values
  ('design-systems-salon', 'Design Systems Salon', 'Design', '2026-11-21T10:00:00', '2026-11-21T18:00:00', 'The Studio Hall', 'Mumbai', 'In person', 1299, 428, 600, true, 4.9, 'https://images.unsplash.com/photo-1558655146-9f40138edfeb?auto=format&fit=crop&w=1200&q=85', '["https://images.unsplash.com/photo-1558655146-9f40138edfeb?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1200&q=85"]'::jsonb, 'A one-day gathering for designers, developers, and product thinkers shaping the systems behind memorable digital products.', 'Design Systems Salon brings the people behind the pixels together for practical conversations about scale, craft, collaboration, and creating products that feel unmistakably human.', '["10:00 — Welcome coffee and introductions","11:00 — The calm design system: talk by Rhea Kapoor","13:00 — Community lunch","15:00 — Hands-on token workshop","17:00 — Open studio and closing drinks"]'::jsonb, '["rhea-kapoor","jules-mehta"]'::jsonb, '["Product design","Systems","Networking"]'::jsonb),
  ('future-food-lab', 'Future Food Lab', 'Food', '2026-12-05T11:00:00', '2026-12-05T19:00:00', 'The Courtyard', 'Bengaluru', 'In person', 899, 287, 400, true, 4.8, 'https://images.unsplash.com/photo-1556910103-1c02745aae4d?auto=format&fit=crop&w=1200&q=85', '["https://images.unsplash.com/photo-1556910103-1c02745aae4d?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=1200&q=85"]'::jsonb, 'Taste, learn, and meet the chefs, growers, and founders building a kinder future for food.', 'Future Food Lab is a sensory festival about what we eat next. Expect intimate chef demos, climate conversations, tastings, and a market full of brilliant local makers.', '["11:00 — Market opens","12:30 — Fermentation masterclass","14:00 — Long-table lunch","16:00 — Food futures panel","18:00 — Sunset tasting menu"]'::jsonb, '["arjun-nair","mira-sen"]'::jsonb, '["Tastings","Sustainability","Workshops"]'::jsonb),
  ('indie-makers-weekend', 'Indie Makers Weekend', 'Community', '2026-12-12T09:00:00', '2026-12-13T17:00:00', 'The Old Press', 'Goa', 'In person', 1499, 192, 300, false, 4.7, 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=1200&q=85', '["https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1492684223066-81342ee5ff30?auto=format&fit=crop&w=1200&q=85"]'::jsonb, 'Two days of honest conversations, focused workshops, and new friendships for independent builders.', 'Bring your half-finished ideas and leave with momentum. Indie Makers Weekend is a generous, low-pressure gathering for founders, freelancers, artists, and curious collaborators.', '["09:00 — Breakfast and desk drop","11:00 — Build in public roundtable","14:00 — Quiet co-working session","18:30 — Makers market","09:30 — Day two skill shares"]'::jsonb, '["jules-mehta","arjun-nair"]'::jsonb, '["Founders","Co-working","Skill shares"]'::jsonb),
  ('night-market-stories', 'Night Market Stories', 'Culture', '2026-11-28T17:00:00', '2026-11-28T23:00:00', 'The Riverfront', 'New Delhi', 'In person', 499, 643, 1000, true, 4.9, 'https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=1200&q=85', '["https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1506157786151-b8491531f063?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1200&q=85"]'::jsonb, 'An after-dark celebration of food, music, independent art, and the stories that make a city feel alive.', 'Night Market Stories turns the riverfront into a moving scrapbook of the city: street food, handmade objects, intimate performances, and the people who make the night worth remembering.', '["17:00 — Gates and market open","18:30 — Street food walk","20:00 — Live storytelling","21:00 — Open-air music","22:30 — Lantern closing"]'::jsonb, '["mira-sen"]'::jsonb, '["Live music","Local food","Art market"]'::jsonb),
  ('product-craft-lab', 'Product Craft Lab', 'Technology', '2027-01-16T10:30:00', '2027-01-16T18:00:00', 'T-Hub Campus', 'Hyderabad', 'Hybrid', 1899, 351, 500, false, 4.8, 'https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1200&q=85', '["https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=1200&q=85"]'::jsonb, 'A practical conference for product teams who care about clarity, momentum, and the details users remember.', 'Product Craft Lab is a focused day of case studies and working sessions for product managers, engineers, researchers, and designers who want to make better decisions together.', '["10:30 — Check-in and coffee","11:30 — The product narrative","13:00 — Lunch and mentor tables","15:00 — Research-to-roadmap lab","17:30 — Closing notes"]'::jsonb, '["rhea-kapoor","jules-mehta"]'::jsonb, '["Product teams","Research","Leadership"]'::jsonb),
  ('sound-and-soul', 'Sound & Soul', 'Music', '2027-02-06T16:00:00', '2027-02-06T23:00:00', 'The Quarry Grounds', 'Pune', 'In person', 999, 824, 1500, false, 4.9, 'https://images.unsplash.com/photo-1501386761578-eac5c94b800a?auto=format&fit=crop&w=1200&q=85', '["https://images.unsplash.com/photo-1501386761578-eac5c94b800a?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1524368535928-5b5e00ddc76b?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1514525253161-7a46d19cd819?auto=format&fit=crop&w=1200&q=85"]'::jsonb, 'An open-air evening of new sounds, warm lights, and the artists shaping the next independent music scene.', 'Sound & Soul is a generous, all-ages night under the stars with four live sets, small food stalls, and enough space to dance or simply listen.', '["16:00 — Doors and vinyl market","17:30 — First set","19:00 — Emerging artists showcase","20:30 — Headline performance","22:15 — Closing DJ set"]'::jsonb, '["mira-sen"]'::jsonb, '["Live sets","Open air","Independent artists"]'::jsonb)
